'use strict';
try{var tg=window.Telegram&&window.Telegram.WebApp;if(tg){tg.expand();tg.ready();try{tg.setHeaderColor('#000000')}catch(e){}var u=tg.initDataUnsafe&&tg.initDataUnsafe.user;if(u&&u.first_name)window.__tgName=u.first_name}}catch(e){}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,8)}
function nowISO(){return new Date().toISOString()}
function today(){return new Date().toISOString().slice(0,10)}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function daysBetween(a,b){return Math.floor((new Date(b)-new Date(a))/(24*60*60*1000))}
function toast(msg,type,duration){type=type||'info';duration=duration||2500;var c=document.getElementById('toasts');if(!c)return;var el=document.createElement('div');el.className='toast '+type;el.textContent=msg;c.appendChild(el);setTimeout(function(){el.style.opacity='0';el.style.transform='translate(-50%,-16px)';el.style.transition='all .4s';setTimeout(function(){el.remove()},400)},duration)}
function haptic(type){try{var h=window.Telegram&&window.Telegram.WebApp&&window.Telegram.WebApp.HapticFeedback;if(!h)return;if(type==='success')h.notificationOccurred('success');else if(type==='error')h.notificationOccurred('error');else h.impactOccurred(type||'light')}catch(e){}}
var AudioCtx=window.AudioContext||window.webkitAudioContext;var audioCtx=null;
function initAudio(){if(!audioCtx){try{audioCtx=new AudioCtx()}catch(e){}}return audioCtx}
function playTone(freq,duration,type,vol){try{var ctx=initAudio();if(!ctx)return;if(ctx.state==='suspended')ctx.resume();var osc=ctx.createOscillator();var gain=ctx.createGain();osc.type=type||'sine';osc.frequency.value=freq;gain.gain.value=vol||0.15;gain.gain.exponentialRampToValueAtTime(0.001,ctx.currentTime+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime);osc.stop(ctx.currentTime+duration)}catch(e){}}
function playClickSound(){playTone(800,0.05,'sine',0.08)}
function playSuccessSound(){playTone(523,0.1,'sine',0.12);setTimeout(function(){playTone(659,0.1,'sine',0.12)},100);setTimeout(function(){playTone(784,0.2,'sine',0.12)},200)}
function playErrorSound(){playTone(200,0.3,'sawtooth',0.1)}
function playAchievementSound(){playTone(523,0.15,'sine',0.15);setTimeout(function(){playTone(659,0.15,'sine',0.15)},150);setTimeout(function(){playTone(784,0.15,'sine',0.15)},300);setTimeout(function(){playTone(1047,0.4,'sine',0.15)},450)}
function playWaterSound(){playTone(600,0.08,'sine',0.1);setTimeout(function(){playTone(800,0.08,'sine',0.1)},80)}
function playLevelUpSound(){playTone(392,0.15,'sine',0.15);setTimeout(function(){playTone(523,0.15,'sine',0.15)},150);setTimeout(function(){playTone(659,0.15,'sine',0.15)},300);setTimeout(function(){playTone(784,0.5,'sine',0.15)},450)}
function backBtn(target){return '<button class="back-btn" onclick="navigate(\''+target+'\')">← Назад</button>'}
function renderTabBar(){var bar=document.getElementById('tabBar');if(!bar)return;var html='';for(var i=0;i<TABS.length;i++){var t=TABS[i];html+='<button class="tab-item '+(t.id===currentPage?'active':'')+'" onclick="navigate(\''+t.id+'\')">';html+='<span class="tab-icon">'+t.emoji+'</span><span class="tab-label">'+t.label+'</span></button>'}bar.innerHTML=html}
function navigate(page){
  if(!page)page='dashboard';
  currentPage=page;
  try{renderTabBar()}catch(e){}
  var main=document.getElementById('app');
  if(!main)return;
  main.innerHTML='';
  var renderers={
    dashboard:renderDashboard,tasks:renderTasks,learning:renderLearning,levels:renderLevels,
    levelDetail:renderLevelDetail,moduleDetail:renderModuleDetail,paths:renderPaths,pathDetail:renderPathDetail,
    courses:renderCourses,courseDetail:renderCourseDetail,methods:renderMethods,domains:renderDomains,
    plan:renderPersonalPlan,ai:renderAI,health:renderHealth,more:renderMore,
    calendar:renderCalendar,stats:renderStats,matrix:renderMatrix,integrations:renderIntegrations,
    metrics:renderMetrics,profile:renderProfile,settings:renderSettings,dbmanager:renderDBManager,
    history:renderHistory,water:renderWater,mood:renderMood,habits:renderHabits,
    goals:renderGoals,timer:renderTimer,notes:renderNotes,focus:renderFocus,
    meds:renderMeds,workouts:renderWorkouts,meditation:renderMeditation,journal:renderJournal,
    media:renderMedia,finance:renderFinance,screenTime:renderScreenTime,english:renderEnglish,
    englishLevel:renderEnglishLevel,storage:renderStorage,recovery:renderRecovery,
    entertainment:renderEntertainment,screentracker:renderScreenTracker,memory:renderMemory,
    iq:renderIQ,eq:renderEQ,neuromodule:renderNeuro,dailyplan:renderDailyPlan,
    watchlist:renderWatchlist,watched:renderWatched,detoxplan:renderDetoxPlan,
    movies:renderMovies,series:renderSeries,books:renderBooks,musiclib:renderMusic,
    gameslib:renderGames,podcastslib:renderPodcasts,theaterlib:renderTheater,artlib:renderArt,
    detailedStats:renderDetailedStats
  };
  var fn=renderers[page];
  if(typeof fn!=='function'){
    main.innerHTML='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">🚧 '+page+'</div><div class="card"><div class="empty"><div class="empty-icon">🚧</div><div class="empty-title">Раздел в разработке</div><div class="empty-text">Функция для "'+page+'" не найдена</div></div></div></div>';
    return;
  }
  try{fn()}catch(e){
    console.error('Рендер ошибка ['+page+']:',e);
    main.innerHTML='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">⚠️ Ошибка</div><div class="card"><div class="empty"><div class="empty-icon">⚠️</div><div class="empty-title">'+esc(e.message||'Ошибка')+'</div><div class="empty-text">Раздел: '+page+'</div></div></div></div>';
  }
  window.scrollTo({top:0});
  if(page==='profile'||page==='dashboard'){try{checkAchievements()}catch(e){}}
}
function openSheet(title,content){var overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML='<div class="modal"><div class="modal-handle"></div><div class="modal-header"><div class="modal-title">'+esc(title)+'</div><button class="modal-close" onclick="closeSheet()">✕</button></div>'+content+'</div>';overlay.onclick=function(e){if(e.target===overlay)closeSheet()};document.body.appendChild(overlay);document.body.style.overflow='hidden';playClickSound()}
function closeSheet(){document.querySelectorAll('.overlay').forEach(function(o){o.remove()});document.body.style.overflow='';playClickSound()}

/* ТЕМЫ + ЭФФЕКТЫ */
function openThemePicker(){var html='<div class="footnote text-tertiary" style="margin-bottom:8px;">🎨 Выбери тему</div>';html+='<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:20px;">';THEMES.forEach(function(t){var active=state.settings.theme===t.id;html+='<button onclick="setTheme(\''+t.id+'\')" style="padding:14px 8px;border-radius:14px;border:2px solid '+(active?'var(--brand)':'transparent')+';background:'+t.color+';color:#fff;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;"><span style="font-size:26px;">'+t.emoji+'</span><span style="font-size:10px;font-weight:700;">'+t.name+'</span></button>'});html+='</div>';html+='<div class="card" style="margin:0;padding:14px 16px;"><div class="row-between mb-2"><div><div class="list-title">🌈 Живые эффекты</div><div class="caption text-tertiary">Дым, волны, снег, огонь</div></div><button class="switch '+(state.settings.effectsEnabled?'on':'')+'" onclick="state.settings.effectsEnabled=!state.settings.effectsEnabled;save();closeSheet();startEffects();toast(\'Ок\',\'success\');"></button></div><div class="row-between"><div><div class="list-title">💪 Интенсивность</div></div><div class="btn-row"><button class="btn btn-ghost btn-xs" onclick="state.settings.effectsIntensity=0.5;save();startEffects();">Слабо</button><button class="btn btn-ghost btn-xs" onclick="state.settings.effectsIntensity=1;save();startEffects();">Средне</button><button class="btn btn-ghost btn-xs" onclick="state.settings.effectsIntensity=2;save();startEffects();">Макс</button></div></div></div>';openSheet('Тема и эффекты',html)}
function setTheme(id){state.settings.theme=id;applyTheme(id);save();haptic('success');playClickSound();closeSheet();toast('Тема изменена','success')}
function applyTheme(id){var themes=THEMES.map(function(t){return t.id});themes.forEach(function(t){document.body.classList.remove('theme-'+t)});document.body.classList.add('theme-'+id);startEffects()}
function startEffects(){
  var overlay=document.getElementById('themeEffect');
  if(!overlay)return;
  overlay.innerHTML='';
  var theme=THEMES.find(function(t){return t.id===state.settings.theme});
  if(!theme||!state.settings.effectsEnabled)return;
  var effect=theme.effects;
  var intensity=state.settings.effectsIntensity||1;
  if(effect==='none')return;
  var count=function(base){return Math.round(base*intensity)};
  if(effect==='stars'){for(var i=0;i<count(15);i++){var s=document.createElement('div');s.className='effect-star';s.style.left=Math.random()*100+'%';s.style.top=Math.random()*100+'%';s.style.animationDelay=Math.random()*3+'s';overlay.appendChild(s)}}
  else if(effect==='rain'){for(var j=0;j<count(20);j++){var d=document.createElement('div');d.className='effect-drop';d.style.left=Math.random()*100+'%';d.style.animationDuration=(Math.random()*1.5+1.5)+'s';d.style.animationDelay=Math.random()*5+'s';d.style.height=(Math.random()*20+12)+'px';overlay.appendChild(d)}}
  else if(effect==='petals'){for(var k=0;k<count(12);k++){var p=document.createElement('div');p.className='effect-petal';p.textContent='🌸';p.style.left=Math.random()*100+'%';p.style.animationDuration=(Math.random()*8+10)+'s';p.style.animationDelay=Math.random()*10+'s';overlay.appendChild(p)}}
  else if(effect==='leaves'){for(var l=0;l<count(10);l++){var lf=document.createElement('div');lf.className='effect-leaf';lf.textContent='🍃';lf.style.left=Math.random()*100+'%';lf.style.animationDuration=(Math.random()*8+8)+'s';lf.style.animationDelay=Math.random()*10+'s';overlay.appendChild(lf)}}
  else if(effect==='snow'){for(var n=0;n<count(15);n++){var sn=document.createElement('div');sn.className='effect-snowflake';sn.textContent='❄';sn.style.left=Math.random()*100+'%';sn.style.animationDuration=(Math.random()*6+8)+'s';sn.style.animationDelay=Math.random()*10+'s';overlay.appendChild(sn)}}
  else if(effect==='waves'){for(var w=0;w<count(3);w++){var wv=document.createElement('div');wv.className='effect-wave';wv.style.bottom=(w*30)+'px';wv.style.animationDelay=(w*1.5)+'s';overlay.appendChild(wv)}}
  else if(effect==='smoke'){for(var sm=0;sm<count(5);sm++){var smk=document.createElement('div');smk.className='effect-smoke';smk.style.left=Math.random()*100+'%';smk.style.animationDuration=(Math.random()*8+12)+'s';smk.style.animationDelay=Math.random()*10+'s';overlay.appendChild(smk)}}
  else if(effect==='sunrays'){for(var sr=0;sr<count(3);sr++){var ray=document.createElement('div');ray.className='effect-ray';ray.style.left=(20+sr*30)+'%';ray.style.animationDelay=(sr*1.5)+'s';overlay.appendChild(ray)}}
  else if(effect==='crystals'){for(var cr=0;cr<count(15);cr++){var dm=document.createElement('div');dm.className='effect-diamond';dm.textContent='◆';dm.style.left=Math.random()*100+'%';dm.style.animationDuration=(Math.random()*8+10)+'s';dm.style.animationDelay=Math.random()*10+'s';overlay.appendChild(dm)}}
  else if(effect==='bats'){for(var b=0;b<count(3);b++){var bat=document.createElement('div');bat.className='effect-fly';bat.textContent='🦇';bat.style.left=Math.random()*100+'%';bat.style.top=Math.random()*50+'%';bat.style.animationDelay=Math.random()*5+'s';overlay.appendChild(bat)}}
  else if(effect==='spiders'){for(var sp=0;sp<count(3);sp++){var spd=document.createElement('div');spd.className='effect-fly';spd.textContent='🕷';spd.style.left=Math.random()*100+'%';spd.style.top=Math.random()*50+'%';spd.style.animationDelay=Math.random()*5+'s';overlay.appendChild(spd)}}
  else if(effect==='aurora'){for(var au=0;au<count(2);au++){var aul=document.createElement('div');aul.className='effect-aurora-layer';aul.style.animationDelay=(au*3)+'s';overlay.appendChild(aul)}}
  else if(effect==='sand'){for(var sd=0;sd<count(20);sd++){var sdust=document.createElement('div');sdust.className='effect-dust';sdust.style.left=Math.random()*100+'%';sdust.style.top=Math.random()*100+'%';sdust.style.animationDuration=(Math.random()*4+4)+'s';sdust.style.animationDelay=Math.random()*6+'s';overlay.appendChild(sdust)}}
  else if(effect==='cyber'){for(var cy=0;cy<count(10);cy++){var cyd=document.createElement('div');cyd.className='effect-code';cyd.textContent='01';cyd.style.left=Math.random()*100+'%';cyd.style.animationDuration=(Math.random()*4+4)+'s';cyd.style.animationDelay=Math.random()*5+'s';overlay.appendChild(cyd)}}
  else if(effect==='ember'){for(var em=0;em<count(20);em++){var ember=document.createElement('div');ember.className='effect-ember';ember.style.left=Math.random()*100+'%';ember.style.bottom=(Math.random()*100)+'px';ember.style.animationDuration=(Math.random()*3+3)+'s';ember.style.animationDelay=Math.random()*4+'s';overlay.appendChild(ember)}}
  else if(effect==='bubbles'){for(var bb=0;bb<count(12);bb++){var bub=document.createElement('div');bub.className='effect-bubble';bub.style.left=Math.random()*100+'%';var size=Math.random()*20+8;bub.style.width=size+'px';bub.style.height=size+'px';bub.style.animationDuration=(Math.random()*8+6)+'s';bub.style.animationDelay=Math.random()*8+'s';overlay.appendChild(bub)}}
  else if(effect==='neon'){for(var nn=0;nn<count(20);nn++){var spark=document.createElement('div');spark.className='effect-spark';spark.style.left=Math.random()*100+'%';spark.style.top=Math.random()*100+'%';spark.style.animationDelay=Math.random()*3+'s';overlay.appendChild(spark)}}
  else if(effect==='fog'){for(var fg=0;fg<count(3);fg++){var fog=document.createElement('div');fog.className='effect-fog';fog.style.top=(fg*30)+'%';fog.style.animationDelay=(fg*3)+'s';overlay.appendChild(fog)}}
  else if(effect==='lightning'){for(var lt=0;lt<1;lt++){var light=document.createElement('div');light.className='effect-lightning';overlay.appendChild(light)}}
  else if(effect==='moon'){var moon=document.createElement('div');moon.className='effect-moon-glow';overlay.appendChild(moon)}
  else if(effect==='galaxy'){for(var gl=0;gl<count(3);gl++){var gal=document.createElement('div');gal.className='effect-galaxy';gal.style.width='200px';gal.style.height='200px';gal.style.left=(Math.random()*80)+'%';gal.style.top=(Math.random()*80)+'%';gal.style.animationDelay=(gl*5)+'s';overlay.appendChild(gal)}}
  else if(effect==='nebula'){for(var nb=0;nb<count(2);nb++){var neb=document.createElement('div');neb.className='effect-nebula';neb.style.width='300px';neb.style.height='300px';neb.style.left=(Math.random()*70)+'%';neb.style.top=(Math.random()*70)+'%';neb.style.animationDelay=(nb*4)+'s';overlay.appendChild(neb)}}
  else if(effect==='code'){for(var cd=0;cd<count(8);cd++){var code=document.createElement('div');code.className='effect-code';code.textContent=Math.random()>0.5?'1':'0';code.style.left=Math.random()*100+'%';code.style.animationDuration=(Math.random()*4+4)+'s';code.style.animationDelay=Math.random()*5+'s';overlay.appendChild(code)}}
  else if(effect==='spark'){for(var sk=0;sk<count(25);sk++){var spk=document.createElement('div');spk.className='effect-spark';spk.style.left=Math.random()*100+'%';spk.style.top=Math.random()*100+'%';spk.style.animationDelay=Math.random()*2+'s';overlay.appendChild(spk)}}
  else if(effect==='stardust'){for(var std=0;std<count(40);std++){var stdust=document.createElement('div');stdust.className='effect-stardust';stdust.style.left=Math.random()*100+'%';stdust.style.top=Math.random()*100+'%';stdust.style.animationDelay=Math.random()*3+'s';overlay.appendChild(stdust)}}
  else if(effect==='holo'){for(var ho=0;ho<count(15);ho++){var holo=document.createElement('div');holo.className='effect-spark';holo.style.left=Math.random()*100+'%';holo.style.top=Math.random()*100+'%';holo.style.background='linear-gradient(45deg,#00ffcc,#ff00aa)';holo.style.animationDelay=Math.random()*3+'s';overlay.appendChild(holo)}}
}

/* ОБУЧЕНИЕ — уровни, модули */
function getLevelProgress(levelId){var level=LEARNING_LEVELS.find(function(l){return l.id===levelId});if(!level)return{done:0,total:0,pct:0};var total=0,done=0;level.modules.forEach(function(mod){mod.lessons.forEach(function(l,idx){total++;if(state.levelProgress&&state.levelProgress[levelId+'_'+mod.id+'_'+idx])done++})});return{done:done,total:total,pct:total>0?Math.round(done/total*100):0}}
function isLevelUnlocked(levelId){var idx=LEARNING_LEVELS.findIndex(function(l){return l.id===levelId});if(idx<=0)return true;var prev=LEARNING_LEVELS[idx-1];return getLevelProgress(prev.id).pct===100}
function isModuleUnlocked(level,moduleIdx){if(moduleIdx===0)return true;var prevMod=level.modules[moduleIdx-1];return prevMod.lessons.every(function(l,idx){return state.levelProgress[level.id+'_'+prevMod.id+'_'+idx]})}
function isLessonUnlocked(level,module,lessonIdx){if(lessonIdx===0)return true;var key=level.id+'_'+module.id+'_'+(lessonIdx-1);return !!state.levelProgress[key]}

/* DASHBOARD */
function renderDashboard(){
  var todayTasks=state.tasks.filter(function(t){return t.created_at&&t.created_at.slice(0,10)===today()});
  var doneToday=todayTasks.filter(function(t){return t.status==='completed'}).length;
  var hour=new Date().getHours();
  var greet=hour<6?'Доброй ночи':hour<12?'Доброе утро':hour<18?'Добрый день':'Добрый вечер';
  var progress=todayTasks.length?Math.round(doneToday/todayTasks.length*100):0;
  var userName=state.profile.name?', '+state.profile.name:'';
  var totalDone=0,totalLessons=0;
  LEARNING_LEVELS.forEach(function(level){var p=getLevelProgress(level.id);totalDone+=p.done;totalLessons+=p.total});
  var overallPct=totalLessons?Math.round(totalDone/totalLessons*100):0;
  var html='<div class="page"><div class="title-xl">'+greet+userName+'</div>';
  html+='<div class="card card-gradient"><div class="row-between" style="margin-bottom:14px;"><div><div style="font-size:13px;opacity:.85;font-weight:600;margin-bottom:6px;">Прогресс дня</div><div style="font-size:40px;font-weight:800;line-height:1;">'+doneToday+'/'+todayTasks.length+'</div></div><div style="font-size:48px;font-weight:800;">'+progress+'%</div></div><div class="progress" style="background:rgba(255,255,255,.25);height:8px;"><div class="progress-fill" style="width:'+progress+'%;background:#fff;"></div></div></div>';
  html+='<div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+(state.stats.streak||0)+'</div><div class="stat-label">Streak</div></div><div class="stat-item"><div class="stat-value">'+overallPct+'%</div><div class="stat-label">Обучение</div></div><div class="stat-item"><div class="stat-value">'+((state.watched||[]).length)+'</div><div class="stat-label">Досуг</div></div></div>';
  html+='<div class="card"><h2>⚡ Быстрые действия</h2><div class="btn-row"><button class="btn btn-ghost btn-sm" onclick="navigate(\'dailyplan\')">📋 План дня</button><button class="btn btn-ghost btn-sm" onclick="navigate(\'stats\')">📊 Стата</button><button class="btn btn-ghost btn-sm" onclick="navigate(\'domains\')">🌐 Домены</button><button class="btn btn-ghost btn-sm" onclick="addTask()">➕ Задача</button><button class="btn btn-ghost btn-sm" onclick="addWater()">💧 Вода</button><button class="btn btn-ghost btn-sm" onclick="quickMoodLog()">💭 Настроение</button></div></div>';
  html+='<div class="card" style="background:linear-gradient(135deg,rgba(167,139,250,.15),rgba(91,158,255,.1));border-color:rgba(167,139,250,.3);"><h2>🎓 Обучение</h2><div class="footnote text-secondary" style="margin-bottom:12px;">5 уровней + 5 модулей</div><button class="btn btn-primary btn-block" onclick="navigate(\'learning\')">Открыть</button></div>';
  html+='<div class="card" style="background:linear-gradient(135deg,rgba(60,220,130,.15),rgba(91,158,255,.1));border-color:rgba(60,220,130,.3);"><h2>🇬🇧 English 125</h2><button class="btn btn-primary btn-block" onclick="navigate(\'english\')">Продолжить</button></div>';
  html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,123,169,.15),rgba(255,169,64,.1));border-color:rgba(255,123,169,.3);"><h2>🎬 Досуг</h2><button class="btn btn-primary btn-block" onclick="navigate(\'entertainment\')">Открыть</button></div>';
  html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,107,107,.15),rgba(255,169,64,.1));border-color:rgba(255,107,107,.3);"><h2>📱 Детокс</h2><button class="btn btn-primary btn-block" onclick="navigate(\'screentracker\')">Открыть</button></div>';
  if(!state.profile.surveyDone){html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,169,64,.15),rgba(255,107,107,.1));border-color:rgba(255,169,64,.3);"><h2>📋 Заполни профиль</h2><button class="btn btn-primary btn-block" onclick="startSurvey()">Начать</button></div>'}
  html+='<div class="insight-card"><div class="insight-title">💎 Мудрость дня</div><div class="insight-text">"Ты не ленивый. Ты либо устал, либо не видишь смысла, либо боишься."</div></div>';
  html+='<div class="card"><h2>📋 Задачи</h2>';
  var pending=state.tasks.filter(function(t){return t.status==='pending'}).slice(0,5);
  if(pending.length){pending.forEach(function(t){html+=taskRow(t)})}else{html+='<div class="empty"><div class="empty-icon">✨</div><div class="empty-title">Всё выполнено</div></div>'}
  html+='</div></div>';
  document.getElementById('app').innerHTML=html;
}
function taskRow(t){var pColors={high:'high',medium:'medium',low:'low'};var checked=t.status==='completed';return '<div class="task-item '+(checked?'completed':'')+'" onclick="editTask(\''+t.id+'\')"><div class="priority-bar '+(pColors[t.priority]||'medium')+'"></div><button class="task-checkbox '+(checked?'checked':'')+'" onclick="event.stopPropagation();toggleTask(\''+t.id+'\')">'+(checked?'✓':'')+'</button><div class="task-content"><div class="task-title">'+esc(t.title)+'</div><div class="task-meta"><span>'+(t.planned_time||0)+' мин</span>'+(t.category?'<span>· '+esc(t.category)+'</span>':'')+'</div></div></div>'}

/* ЗАДАЧИ */
var taskFilter='all';var taskSearch='';
function renderTasks(){var counts={all:state.tasks.length,pending:state.tasks.filter(function(t){return t.status==='pending'}).length,completed:state.tasks.filter(function(t){return t.status==='completed'}).length};var filtered=state.tasks.slice();if(taskFilter!=='all')filtered=filtered.filter(function(t){return t.status===taskFilter});if(taskSearch){var q=taskSearch.toLowerCase();filtered=filtered.filter(function(t){return t.title.toLowerCase().indexOf(q)>=0})}var html='<div class="page">'+backBtn('dashboard')+'<div class="row-between" style="margin-bottom:20px;"><div class="title-xl" style="margin:0;">✅ Задачи</div><button class="btn btn-primary btn-sm" onclick="addTask()">+ Новая</button></div>';html+='<div class="search-bar"><span style="color:var(--text-3);font-size:18px;">🔍</span><input type="search" placeholder="Поиск..." value="'+esc(taskSearch)+'" oninput="taskSearch=this.value;renderTasks()"/></div>';html+='<div class="segmented" style="margin-bottom:18px;"><button class="segmented-item '+(taskFilter==='all'?'active':'')+'" onclick="taskFilter=\'all\';renderTasks()">Все ('+counts.all+')</button><button class="segmented-item '+(taskFilter==='pending'?'active':'')+'" onclick="taskFilter=\'pending\';renderTasks()">Активные ('+counts.pending+')</button><button class="segmented-item '+(taskFilter==='completed'?'active':'')+'" onclick="taskFilter=\'completed\';renderTasks()">Готовые ('+counts.completed+')</button></div>';if(filtered.length){filtered.forEach(function(t){html+=taskRow(t)})}else{html+='<div class="empty"><div class="empty-icon">📋</div><div class="empty-title">'+(taskSearch?'Ничего':'Нет задач')+'</div></div>'}html+='</div>';document.getElementById('app').innerHTML=html}
function addTask(){openSheet('Новая задача','<div class="field"><input type="text" id="t-title" placeholder="Название" autofocus/></div><div class="row" style="gap:8px;"><div style="flex:1;"><label class="field-label">Время</label><input type="number" id="t-time" value="30" min="5" step="5"/></div><div style="flex:1;"><label class="field-label">Приоритет</label><select id="t-priority"><option value="low">🟢</option><option value="medium" selected>🟡</option><option value="high">🔴</option></select></div></div><button class="btn btn-primary btn-block mt-3" onclick="saveTask()">Добавить</button>');setTimeout(function(){var el=document.getElementById('t-title');if(el)el.focus()},100)}
function saveTask(){var title=((document.getElementById('t-title')||{}).value||'').trim();if(!title)return toast('Введите название','error');state.tasks.unshift({id:uid(),title:title,planned_time:parseInt((document.getElementById('t-time')||{}).value)||30,actual_time:0,status:'pending',priority:(document.getElementById('t-priority')||{}).value||'medium',category:'Работа',created_at:nowISO()});save();playSuccessSound();closeSheet();toast('Задача добавлена','success');haptic('success');checkAchievements();if(currentPage==='tasks')renderTasks();else renderDashboard()}
function toggleTask(id){var t=state.tasks.find(function(x){return x.id===id});if(!t)return;t.status=t.status==='completed'?'pending':'completed';t.actual_time=t.status==='completed'?(t.planned_time||0):0;if(t.status==='completed')state.stats.totalTasksDone=(state.stats.totalTasksDone||0)+1;save();if(t.status==='completed'){playSuccessSound();toast('✓ Выполнено','success')}else{playClickSound()}haptic('success');checkAchievements();if(currentPage==='tasks')renderTasks();else renderDashboard()}
function editTask(id){var t=state.tasks.find(function(x){return x.id===id});if(!t)return;openSheet('Редактировать','<div class="field"><input type="text" id="e-title" value="'+esc(t.title)+'"/></div><button class="btn btn-primary btn-block" onclick="updateTask(\''+id+'\')">Сохранить</button><button class="btn btn-danger btn-block mt-2" onclick="deleteTask(\''+id+'\')">Удалить</button>')}
function updateTask(id){var t=state.tasks.find(function(x){return x.id===id});if(!t)return;t.title=(document.getElementById('e-title')||{}).value||t.title;save();playSuccessSound();closeSheet();toast('Сохранено','success');renderTasks()}
function deleteTask(id){if(!confirm('Удалить?'))return;state.tasks=state.tasks.filter(function(t){return t.id!==id});save();playErrorSound();closeSheet();toast('Удалено','info');renderTasks()}

/* ОБУЧЕНИЕ */
function renderLearning(){var totalDone=0,totalLessons=0;LEARNING_LEVELS.forEach(function(level){var p=getLevelProgress(level.id);totalDone+=p.done;totalLessons+=p.total});var overallPct=totalLessons?Math.round(totalDone/totalLessons*100):0;var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">🎓 Обучение</div>';html+='<div class="card card-gradient"><div style="opacity:.9;font-size:13px;margin-bottom:6px;">Общий прогресс</div><div style="font-size:44px;font-weight:800;line-height:1;margin-bottom:12px;">'+overallPct+'%</div><div style="opacity:.9;font-size:13px;">'+totalDone+' из '+totalLessons+'</div><div class="progress" style="margin-top:14px;background:rgba(255,255,255,.25);height:8px;"><div class="progress-fill" style="width:'+overallPct+'%;background:#fff;"></div></div></div>';html+='<div class="card"><h2>🌱 5 уровней</h2><button class="btn btn-primary btn-block" onclick="navigate(\'levels\')">Открыть</button></div>';html+='<div class="card"><h2>🧠 Память</h2><button class="btn btn-primary btn-block" onclick="navigate(\'memory\')">Открыть</button></div>';html+='<div class="card"><h2>🎯 IQ</h2><button class="btn btn-primary btn-block" onclick="navigate(\'iq\')">Открыть</button></div>';html+='<div class="card"><h2>❤️ EQ</h2><button class="btn btn-primary btn-block" onclick="navigate(\'eq\')">Открыть</button></div>';html+='<div class="card"><h2>💰 Финансы</h2><button class="btn btn-primary btn-block" onclick="navigate(\'finance\')">Открыть</button></div>';html+='<div class="card"><h2>🔬 Нейро</h2><button class="btn btn-primary btn-block" onclick="navigate(\'neuromodule\')">Открыть</button></div>';html+='<div class="card"><h2>🗺 Пути</h2><button class="btn btn-ghost btn-block" onclick="navigate(\'paths\')">Открыть</button></div>';html+='<div class="card"><h2>📚 Курсы</h2><button class="btn btn-ghost btn-block" onclick="navigate(\'courses\')">Открыть</button></div>';html+='<div class="card"><h2>💎 Методики</h2><button class="btn btn-ghost btn-block" onclick="navigate(\'methods\')">Открыть</button></div>';html+='</div>';document.getElementById('app').innerHTML=html}
function renderLevels(){var html='<div class="page">'+backBtn('learning')+'<div class="title-xl">🌱 5 уровней</div>';LEARNING_LEVELS.forEach(function(level){var p=getLevelProgress(level.id);var unlocked=isLevelUnlocked(level.id);var completed=p.pct===100;var cls='level-card';if(completed)cls+=' completed';else if(!unlocked)cls+=' locked';else if(p.pct>0)cls+=' active';html+='<div class="'+cls+'" onclick="'+(unlocked?'openLevel(\''+level.id+'\')':'toast(\'Заверши предыдущий\',\'warning\')')+'"><div class="level-header"><div class="level-num">'+(completed?'✓':level.num)+'</div><div class="level-info"><div class="level-title">'+level.emoji+' '+level.title+'</div><div class="level-subtitle">'+level.subtitle+'</div><div class="level-meta"><span>'+level.modules.length+' модулей</span></div></div></div><div class="level-desc">'+level.desc+'</div>';if(unlocked&&p.pct>0)html+='<div class="progress"><div class="progress-fill" style="width:'+p.pct+'%;"></div></div>';html+='</div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openLevel(levelId){currentLevelId=levelId;navigate('levelDetail')}
function renderLevelDetail(){var level=LEARNING_LEVELS.find(function(l){return l.id===currentLevelId});if(!level){navigate('learning');return}var p=getLevelProgress(level.id);var html='<div class="page">'+backBtn('levels');html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:64px;margin-bottom:12px;">'+level.emoji+'</div><div class="title-xl" style="margin-bottom:8px;">Уровень '+level.num+': '+level.title+'</div><div class="footnote text-secondary" style="max-width:340px;margin:0 auto;">'+level.desc+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+p.done+'/'+p.total+'</span></div><div class="progress"><div class="progress-fill" style="width:'+p.pct+'%;"></div></div></div>';html+='<div class="card"><h2>📦 Модули</h2>';level.modules.forEach(function(mod,i){var unlocked=isModuleUnlocked(level,i);var modDone=mod.lessons.every(function(l,idx){return state.levelProgress[level.id+'_'+mod.id+'_'+idx]});var modCount=mod.lessons.filter(function(l,idx){return state.levelProgress[level.id+'_'+mod.id+'_'+idx]}).length;var cls='module-card';if(modDone)cls+=' completed';else if(!unlocked)cls+=' locked';html+='<div class="'+cls+'" onclick="'+(unlocked?'openModule(\''+level.id+'\',\''+mod.id+'\')':'toast(\'Сначала предыдущий\',\'warning\')')+'"><div class="module-header"><div class="module-icon">'+(modDone?'✓':mod.emoji)+'</div><div class="module-info"><div class="module-title">'+mod.title+'</div><div class="module-meta">'+modCount+'/'+mod.lessons.length+' уроков'+(unlocked?'':' · 🔒')+'</div></div></div><div class="module-desc">'+mod.desc+'</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openModule(levelId,moduleId){currentLevelId=levelId;currentModuleId=moduleId;navigate('moduleDetail')}
function renderModuleDetail(){var level=LEARNING_LEVELS.find(function(l){return l.id===currentLevelId});if(!level){navigate('learning');return}var module=level.modules.find(function(m){return m.id===currentModuleId});if(!module){navigate('levelDetail');return}var doneCount=module.lessons.filter(function(l,idx){return state.levelProgress[level.id+'_'+module.id+'_'+idx]}).length;var html='<div class="page">'+backBtn('levelDetail');html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:56px;margin-bottom:12px;">'+module.emoji+'</div><div class="title-xl" style="margin-bottom:8px;">'+module.title+'</div><div class="footnote text-secondary" style="max-width:340px;margin:0 auto;">'+module.desc+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+doneCount+'/'+module.lessons.length+'</span></div><div class="progress"><div class="progress-fill" style="width:'+Math.round(doneCount/module.lessons.length*100)+'%;"></div></div></div>';html+='<div class="card"><h2>📖 Уроки</h2>';module.lessons.forEach(function(lesson,i){var key=level.id+'_'+module.id+'_'+i;var isDone=!!state.levelProgress[key];var unlocked=isLessonUnlocked(level,module,i);var cls='lesson-row';if(isDone)cls+=' done';else if(!unlocked)cls+=' locked';else cls+=' current';html+='<div class="'+cls+'" onclick="'+(unlocked?'openLesson('+i+')':'toast(\'Сначала предыдущий\',\'warning\')')+'"><div class="lesson-num">'+(isDone?'✓':(i+1))+'</div><div class="lesson-title">'+lesson.title+'</div><div style="color:var(--text-4);font-size:20px;">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openLesson(idx){currentLessonIdx=idx;var level=LEARNING_LEVELS.find(function(l){return l.id===currentLevelId});if(!level)return;var module=level.modules.find(function(m){return m.id===currentModuleId});if(!module)return;var lesson=module.lessons[idx];if(!lesson)return;var key=level.id+'_'+module.id+'_'+idx;var isDone=!!state.levelProgress[key];var html='<div class="page">'+backBtn('moduleDetail');html+='<div style="margin-bottom:20px;"><div class="footnote text-tertiary" style="margin-bottom:8px;">Уровень '+level.num+' · '+module.title+' · Урок '+(idx+1)+'/'+module.lessons.length+'</div><div style="font-size:26px;font-weight:800;line-height:1.2;">'+lesson.title+'</div></div>';html+='<div class="card" style="padding:20px;">';html+='<div class="lesson-section"><div class="lesson-section-title">📚 Теория</div><div class="lesson-content">'+formatLesson(lesson.theory)+'</div></div>';html+='<div class="lesson-section practice"><div class="lesson-section-title">🎯 Практика</div><div class="lesson-content">'+esc(lesson.practice)+'</div></div>';html+='<div class="lesson-section reflection"><div class="lesson-section-title">💭 Рефлексия</div><div class="lesson-content">'+esc(lesson.reflection)+'</div></div>';html+='</div>';if(!isDone){html+='<button class="btn btn-primary btn-block" onclick="completeLesson()">✓ Изучено</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:14px;font-size:14px;">✓ Урок изучен</div>';if(idx<module.lessons.length-1){html+='<button class="btn btn-primary btn-block mt-3" onclick="openLesson('+(idx+1)+')">Следующий →</button>'}else{html+='<button class="btn btn-success btn-block mt-3" onclick="navigate(\'moduleDetail\')">Модуль завершён ✓</button>'}}html+='</div>';document.getElementById('app').innerHTML=html;window.scrollTo({top:0})}
function formatLesson(text){var h=esc(text);h=h.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');h=h.replace(/^• (.+)$/gm,'<li>$1</li>');h=h.replace(/(<li>[\s\S]*?<\/li>)(?!\s*<li>)/g,'<ul>$1</ul>');h=h.replace(/\n\n/g,'</p><p>');h=h.replace(/\n/g,'<br>');return '<p>'+h+'</p>'}
function completeLesson(){var level=LEARNING_LEVELS.find(function(l){return l.id===currentLevelId});if(!level)return;var module=level.modules.find(function(m){return m.id===currentModuleId});if(!module)return;var key=level.id+'_'+module.id+'_'+currentLessonIdx;if(!state.levelProgress)state.levelProgress={};state.levelProgress[key]=true;save();playSuccessSound();haptic('success');toast('✓ Урок изучен!','success');checkAchievements();openLesson(currentLessonIdx)}

/* МОДУЛИ ПАМЯТЬ/IQ/EQ/ФИНАНСЫ/НЕЙРО */
function renderMemory(){renderModuleList('memory')}
function renderIQ(){renderModuleList('iq')}
function renderEQ(){renderModuleList('eq')}
function renderFinance(){renderModuleList('finance')}
function renderNeuro(){renderModuleList('neuro')}
function renderModuleList(moduleKey){var map={memory:window.__MEMORY_MODULE||[],iq:window.__IQ_MODULE||[],eq:window.__EQ_MODULE||[],finance:window.__FINANCE_MODULE||[],neuro:window.__NEURO_MODULE||[]};var list=map[moduleKey]||[];var titles={memory:'🧠 Память',iq:'🎯 IQ',eq:'❤️ EQ',finance:'💰 Финансы',neuro:'🔬 Нейро'};if(!list.length){document.getElementById('app').innerHTML='<div class="page">'+backBtn('learning')+'<div class="title-xl">'+titles[moduleKey]+'</div><div class="card"><div class="empty"><div class="empty-icon">📭</div><div class="empty-title">Модуль не загружен</div></div></div></div>';return}var html='<div class="page">'+backBtn('learning')+'<div class="title-xl">'+titles[moduleKey]+'</div>';html+='<div class="card"><div class="footnote text-secondary">'+list.length+' уроков</div></div>';list.forEach(function(lesson,i){var done=state.memoryTraining&&state.memoryTraining.indexOf(lesson.id)>=0;var cls='lesson-row'+(done?' done':'');html+='<div class="'+cls+'" onclick="openModuleLesson(\''+moduleKey+'\','+i+')"><div class="lesson-num">'+(done?'✓':(i+1))+'</div><div class="lesson-title">'+lesson.title+'</div><div style="color:var(--text-4);font-size:20px;">›</div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openModuleLesson(moduleKey,idx){var map={memory:window.__MEMORY_MODULE||[],iq:window.__IQ_MODULE||[],eq:window.__EQ_MODULE||[],finance:window.__FINANCE_MODULE||[],neuro:window.__NEURO_MODULE||[]};var list=map[moduleKey]||[];var lesson=list[idx];if(!lesson)return;var done=state.memoryTraining&&state.memoryTraining.indexOf(lesson.id)>=0;var html='<div style="margin-bottom:16px;"><div class="footnote text-tertiary" style="margin-bottom:8px;">Урок '+(idx+1)+'/'+list.length+'</div><div style="font-size:22px;font-weight:800;">'+lesson.title+'</div></div>';html+='<div class="card"><div class="lesson-section"><div class="lesson-section-title">📚 Теория</div><div class="lesson-content">'+formatLesson(lesson.theory||'')+'</div></div></div>';html+='<div class="card"><div class="lesson-section practice"><div class="lesson-section-title">🎯 Практика</div><div class="lesson-content">'+esc(lesson.practice||'')+'</div></div></div>';if(lesson.memory)html+='<div class="card"><div class="lesson-section memory"><div class="lesson-section-title">🧠 Память</div><div class="lesson-content">'+esc(lesson.memory)+'</div></div></div>';if(lesson.keywords)html+='<div class="card"><div class="footnote text-tertiary">🏷 '+esc(lesson.keywords)+'</div></div>';if(!done){html+='<button class="btn btn-primary btn-block mt-3" onclick="completeModuleLesson(\''+moduleKey+'\','+idx+')">✓ Изучено</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:12px;">✓ Изучено</div>'}openSheet(lesson.title,html)}
function completeModuleLesson(moduleKey,idx){var map={memory:window.__MEMORY_MODULE||[],iq:window.__IQ_MODULE||[],eq:window.__EQ_MODULE||[],finance:window.__FINANCE_MODULE||[],neuro:window.__NEURO_MODULE||[]};var list=map[moduleKey]||[];var lesson=list[idx];if(!lesson)return;if(!state.memoryTraining)state.memoryTraining=[];if(state.memoryTraining.indexOf(lesson.id)<0)state.memoryTraining.push(lesson.id);save();playSuccessSound();haptic('success');toast('✓ Изучено!','success');checkAchievements();closeSheet();renderModuleList(moduleKey)}

/* ENGLISH */
function renderEnglish(){var all=window.__ENGLISH_125||[];var totalDone=0;all.forEach(function(l){if(state.englishProgress&&state.englishProgress[l.id])totalDone++});var pct=all.length?Math.round(totalDone/all.length*100):0;var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">🇬🇧 Английский 125</div>';html+='<div class="card card-gradient"><div style="opacity:.9;font-size:13px;margin-bottom:6px;">Прогресс</div><div style="font-size:44px;font-weight:800;">'+pct+'%</div><div style="opacity:.9;font-size:13px;margin-top:8px;">'+totalDone+' из '+all.length+'</div><div class="progress" style="margin-top:14px;background:rgba(255,255,255,.25);height:8px;"><div class="progress-fill" style="width:'+pct+'%;background:#fff;"></div></div></div>';['A1','A2','B1','B2','C1'].forEach(function(lvl){var lessons=all.filter(function(l){return l.level===lvl});var done=lessons.filter(function(l){return state.englishProgress&&state.englishProgress[l.id]}).length;var lpct=lessons.length?Math.round(done/lessons.length*100):0;var cls='level-card';if(lpct===100)cls+=' completed';else if(lpct>0)cls+=' active';html+='<div class="'+cls+'" onclick="openEnglishLvl(\''+lvl+'\')"><div class="level-header"><div class="level-num">'+lvl+'</div><div class="level-info"><div class="level-title">'+lvl+' — '+lessons.length+' уроков</div><div class="level-subtitle">'+done+'/'+lessons.length+'</div></div></div><div class="progress"><div class="progress-fill" style="width:'+lpct+'%;"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openEnglishLvl(lvl){var all=window.__ENGLISH_125||[];var lessons=all.filter(function(l){return l.level===lvl});var html='<div class="page">'+backBtn('english')+'<div class="title-xl">'+lvl+'</div>';html+='<div class="card"><h2>'+lessons.length+' уроков</h2>';lessons.forEach(function(lesson,i){var isDone=state.englishProgress&&state.englishProgress[lesson.id];html+='<div class="lesson-row '+(isDone?'done':'')+'" onclick="openEnglishLess(\''+lesson.id+'\')"><div class="lesson-num">'+(isDone?'✓':(i+1))+'</div><div class="lesson-title">'+lesson.title+'</div><div style="color:var(--text-4);font-size:20px;">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function renderEnglishLevel(){renderEnglish()}
function openEnglishLess(lessonId){var all=window.__ENGLISH_125||[];var lesson=all.find(function(l){return l.id===lessonId});if(!lesson)return;var isDone=state.englishProgress&&state.englishProgress[lesson.id];var html='<div style="margin-bottom:16px;"><div class="footnote text-tertiary" style="margin-bottom:8px;">'+lesson.level+' · '+lesson.id+'</div><div style="font-size:22px;font-weight:800;">'+lesson.title+'</div></div>';html+='<div class="card"><div class="lesson-section"><div class="lesson-section-title">📚 Теория</div><div class="lesson-content">'+formatLesson(lesson.theory||'')+'</div></div></div>';html+='<div class="card"><div class="lesson-section practice"><div class="lesson-section-title">🎯 Практика</div><div class="lesson-content">'+esc(lesson.practice||'')+'</div></div></div>';if(lesson.memory)html+='<div class="card"><div class="lesson-section memory"><div class="lesson-section-title">🧠 Память</div><div class="lesson-content">'+esc(lesson.memory)+'</div></div></div>';if(lesson.keywords)html+='<div class="card"><div class="footnote text-tertiary">🏷 '+esc(lesson.keywords)+'</div></div>';if(!isDone){html+='<button class="btn btn-primary btn-block mt-3" onclick="completeEnglishLess(\''+lesson.id+'\')">✓ Изучено</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:12px;">✓ Изучено</div>'}openSheet(lesson.title,html)}
function completeEnglishLess(lessonId){if(!state.englishProgress)state.englishProgress={};state.englishProgress[lessonId]=true;save();playSuccessSound();haptic('success');toast('✓ Изучено!','success');checkAchievements();closeSheet();renderEnglish()}

/* ПУТИ */
function renderPaths(){var html='<div class="page">'+backBtn('learning')+'<div class="title-xl">🗺 Пути</div>';PATHS_LIBRARY.forEach(function(p){var userPath=state.paths.find(function(x){return x.id===p.id});var completed=userPath?(userPath.completedSteps||[]).length:0;var progress=Math.round(completed/p.steps.length*100);html+='<div class="card" style="cursor:pointer;" onclick="openPath(\''+p.id+'\')"><div style="display:flex;gap:14px;align-items:center;margin-bottom:12px;"><div style="width:56px;height:56px;border-radius:18px;background:var(--surface-3);display:grid;place-items:center;font-size:28px;flex-shrink:0;">'+p.emoji+'</div><div style="flex:1;"><div style="font-size:17px;font-weight:800;margin-bottom:4px;">'+p.title+'</div><div class="footnote text-secondary">'+completed+'/'+p.steps.length+' · '+p.category+'</div></div><div class="list-chevron">›</div></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openPath(id){currentPathId=id;navigate('pathDetail')}
function renderPathDetail(){var p=PATHS_LIBRARY.find(function(x){return x.id===currentPathId});if(!p){navigate('paths');return}var userPath=state.paths.find(function(x){return x.id===p.id});if(!userPath){userPath={id:p.id,completedSteps:[],startedAt:nowISO()};state.paths.push(userPath);save()}var completed=userPath.completedSteps||[];var progress=Math.round(completed.length/p.steps.length*100);var html='<div class="page">'+backBtn('paths');html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:64px;margin-bottom:12px;">'+p.emoji+'</div><div class="title-xl">'+p.title+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+progress+'%</span></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>';html+='<div class="card"><h2>Шаги</h2>';p.steps.forEach(function(step,i){var isDone=completed.indexOf(i)>=0;var isActive=!isDone&&(i===0||completed.indexOf(i-1)>=0);var isLocked=!isDone&&!isActive;var cls='path-step';if(isDone)cls+=' completed';else if(isActive)cls+=' active';else if(isLocked)cls+=' locked';html+='<div class="'+cls+'" onclick="'+(isLocked?'':'openStep('+i+')')+'"><div class="path-step-num">'+(isDone?'✓':(i+1))+'</div><div class="path-step-body"><div class="path-step-title">'+step.title+'</div><div class="path-step-desc">'+(isDone||isActive?step.desc:'🔒')+'</div></div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openStep(idx){var p=PATHS_LIBRARY.find(function(x){return x.id===currentPathId});if(!p)return;var step=p.steps[idx];if(!step)return;var userPath=state.paths.find(function(x){return x.id===p.id});var isDone=userPath&&(userPath.completedSteps||[]).indexOf(idx)>=0;var html='<div class="card"><h2>📋 Задача</h2><div style="font-size:15px;line-height:1.6;">'+step.desc+'</div></div>';html+='<div class="insight-card"><div class="insight-title">💎 Секрет</div><div class="insight-text">'+step.secret+'</div></div>';if(!isDone){html+='<button class="btn btn-primary btn-block mt-4" onclick="completeStep('+idx+')">✓ Отметить</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:12px;">✓ Выполнено</div>'}openSheet(step.title,html)}
function completeStep(idx){var userPath=state.paths.find(function(x){return x.id===currentPathId});if(!userPath)return;if(!userPath.completedSteps)userPath.completedSteps=[];if(userPath.completedSteps.indexOf(idx)<0){userPath.completedSteps.push(idx);save();playSuccessSound();toast('✓ Шаг выполнен!','success');haptic('success');checkAchievements();closeSheet();renderPathDetail()}}

/* КУРСЫ */
function renderCourses(){var html='<div class="page">'+backBtn('learning')+'<div class="title-xl">📚 Курсы</div>';COURSES_LIBRARY.forEach(function(c){var userCourse=state.courses.find(function(x){return x.id===c.id});var completed=userCourse?(userCourse.completedLessons||[]).length:0;var progress=Math.round(completed/c.lessons.length*100);html+='<div class="course-card" onclick="openCourse(\''+c.id+'\')"><div class="course-header"><div class="course-emoji">'+c.emoji+'</div><div class="course-info"><div class="course-title">'+c.title+'</div><div class="course-meta">'+completed+'/'+c.lessons.length+' · '+progress+'%</div></div></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openCourse(id){var c=COURSES_LIBRARY.find(function(x){return x.id===id});if(!c)return;var userCourse=state.courses.find(function(x){return x.id===id});if(!userCourse){userCourse={id:id,completedLessons:[],startedAt:nowISO()};state.courses.push(userCourse);save()}var completed=userCourse.completedLessons||[];var progress=Math.round(completed.length/c.lessons.length*100);var html='<div class="page">'+backBtn('courses');html+='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:64px;margin-bottom:12px;">'+c.emoji+'</div><div class="title-xl">'+c.title+'</div></div>';html+='<div class="card"><div class="row-between mb-2"><span class="subhead">Прогресс</span><span class="subhead text-secondary">'+completed.length+'/'+c.lessons.length+'</span></div><div class="progress"><div class="progress-fill" style="width:'+progress+'%;"></div></div></div>';html+='<div class="card"><h2>📚 Уроки</h2>';c.lessons.forEach(function(lesson,i){var isDone=completed.indexOf(i)>=0;html+='<div class="lesson-row '+(isDone?'done':'')+'" onclick="openCourseLesson(\''+c.id+'\','+i+')"><div class="lesson-num">'+(isDone?'✓':(i+1))+'</div><div class="lesson-title">'+lesson.title+'</div><div style="color:var(--text-4);font-size:20px;">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function renderCourseDetail(){renderCourses()}
function openCourseLesson(courseId,idx){var c=COURSES_LIBRARY.find(function(x){return x.id===courseId});if(!c)return;var lesson=c.lessons[idx];if(!lesson)return;var userCourse=state.courses.find(function(x){return x.id===courseId});var isDone=userCourse&&(userCourse.completedLessons||[]).indexOf(idx)>=0;var html='<div style="margin-bottom:16px;"><div class="footnote text-tertiary" style="margin-bottom:8px;">Урок '+(idx+1)+'/'+c.lessons.length+'</div><div style="font-size:22px;font-weight:800;">'+lesson.title+'</div></div>';html+='<div class="card"><div style="font-size:15px;line-height:1.7;">'+esc(lesson.content)+'</div></div>';if(!isDone){html+='<button class="btn btn-primary btn-block mt-3" onclick="completeCourseLesson(\''+courseId+'\','+idx+')">✓ Изучено</button>'}else{html+='<div class="badge badge-success" style="display:block;text-align:center;padding:12px;">✓ Изучено</div>'}openSheet(lesson.title,html)}
function completeCourseLesson(courseId,idx){var userCourse=state.courses.find(function(x){return x.id===courseId});if(!userCourse)return;if(!userCourse.completedLessons)userCourse.completedLessons=[];if(userCourse.completedLessons.indexOf(idx)<0){userCourse.completedLessons.push(idx);save();playSuccessSound();toast('✓ Урок изучен!','success');haptic('success');checkAchievements();closeSheet();openCourse(courseId)}}

/* МЕТОДИКИ */
function renderMethods(){var html='<div class="page">'+backBtn('learning')+'<div class="title-xl">💎 Методики</div>';METHODS_LIBRARY.forEach(function(m){html+='<div class="method-card" onclick="openMethod(\''+m.id+'\')"><div class="method-header"><div class="method-emoji">'+m.emoji+'</div><div style="flex:1;"><div class="method-title">'+m.title+'</div><div class="method-cat">'+m.category+'</div></div><div class="list-chevron">›</div></div><div class="method-desc">'+m.desc+'</div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openMethod(id){var m=METHODS_LIBRARY.find(function(x){return x.id===id});if(!m)return;var html='<div style="text-align:center;margin-bottom:20px;"><div style="font-size:56px;margin-bottom:12px;">'+m.emoji+'</div><div style="font-size:22px;font-weight:800;margin-bottom:6px;">'+m.title+'</div><div class="footnote text-secondary">'+m.category+'</div></div>';html+='<div class="card"><div class="footnote text-secondary">'+m.desc+'</div></div>';html+='<div class="card"><h2>📋 Шаги</h2>';m.steps.forEach(function(step,i){html+='<div style="display:flex;gap:12px;padding:8px 0;"><div style="width:24px;height:24px;border-radius:50%;background:var(--brand);color:#fff;display:grid;place-items:center;flex-shrink:0;font-size:12px;font-weight:700;">'+(i+1)+'</div><div style="flex:1;font-size:14px;line-height:1.5;">'+step+'</div></div>'});html+='</div>';html+='<div class="insight-card"><div class="insight-title">🔬 База</div><div class="insight-text">'+m.base+'</div></div>';openSheet(m.title,html)}

/* ДОМЕНЫ */
function getAverageDomainScore(domainId){var history=state.domainHistory||{};var dates=Object.keys(history).slice(-7);if(dates.length===0)return 5;var sum=0,count=0;dates.forEach(function(d){if(history[d]&&history[d][domainId]!==undefined){sum+=history[d][domainId];count++}});return count>0?Math.round(sum/count*10)/10:5}
function renderDomains(){var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">🌐 10 доменов</div><div class="footnote text-secondary" style="margin-bottom:16px;">Оцени 1-10. План строится автоматически.</div>';var todayScores=(state.domainScores||{})[today()]||{};var totalScore=0,count=0;DOMAINS.forEach(function(d){if(todayScores[d.id]){totalScore+=todayScores[d.id];count++}});var avg=count>0?Math.round(totalScore/count*10)/10:0;html+='<div class="card card-gradient"><div style="opacity:.9;font-size:13px;margin-bottom:6px;">Средний балл</div><div style="font-size:44px;font-weight:800;line-height:1;">'+avg+'/10</div><div style="opacity:.9;font-size:13px;margin-top:8px;">'+count+' из '+DOMAINS.length+' оценено</div></div>';DOMAINS.forEach(function(d){var score=todayScores[d.id]||0;var pct=score*10;var avgScore=getAverageDomainScore(d.id);html+='<div class="domain-card" onclick="openDomain(\''+d.id+'\')"><div class="domain-header"><div class="domain-icon" style="background:'+d.color+'20;color:'+d.color+';">'+d.emoji+'</div><div style="flex:1;"><div class="domain-title">'+d.name+'</div><div class="domain-score">'+(score>0?'Сегодня: '+score+'/10':'Не оценено')+(avgScore>0?' · Среднее: '+avgScore:'')+'</div></div><div class="list-chevron">›</div></div><div class="domain-bar"><div class="domain-bar-fill" style="width:'+pct+'%;background:'+d.color+';"></div></div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function openDomain(domainId){var d=DOMAINS.find(function(x){return x.id===domainId});if(!d)return;var todayScores=(state.domainScores||{})[today()]||{};var score=todayScores[domainId]||5;var html='<div style="text-align:center;margin-bottom:20px;"><div style="font-size:56px;margin-bottom:12px;">'+d.emoji+'</div><div style="font-size:22px;font-weight:800;margin-bottom:6px;">'+d.name+'</div><div class="footnote text-secondary">'+d.desc+'</div></div>';html+='<div class="card"><h2>Оцени сегодня</h2><div style="text-align:center;padding:16px 0;"><div style="font-size:48px;font-weight:800;color:'+d.color+';" id="domainScoreDisplay">'+score+'</div><div class="footnote text-secondary">из 10</div></div><input type="range" min="1" max="10" value="'+score+'" style="width:100%;margin:12px 0;" oninput="document.getElementById(\'domainScoreDisplay\').textContent=this.value;" id="domainScoreRange"/><button class="btn btn-primary btn-block" onclick="saveDomainScore(\''+domainId+'\')">Сохранить</button></div>';html+='<div class="card"><h2>📊 Метрики</h2>';d.metrics.forEach(function(m){var todayMetrics=(state.metrics||{})[today()]||{};var val=todayMetrics[m.id]||'—';html+='<div class="metric-row"><div><div class="metric-label">'+m.label+'</div><div class="metric-target">Цель: '+m.target+'</div></div><div class="metric-value">'+val+'</div></div>'});html+='</div>';openSheet(d.name,html)}
function saveDomainScore(domainId){var range=document.getElementById('domainScoreRange');if(!range)return;var score=parseInt(range.value);var t=today();if(!state.domainScores)state.domainScores={};if(!state.domainScores[t])state.domainScores[t]={};state.domainScores[t][domainId]=score;if(!state.domainHistory)state.domainHistory={};if(!state.domainHistory[t])state.domainHistory[t]={};state.domainHistory[t][domainId]=score;save();playSuccessSound();toast('✓ Сохранено','success');haptic('success');closeSheet();renderDomains()}

/* МЕТРИКИ */
function renderMetrics(){var html='<div class="page">'+backBtn('more')+'<div class="title-xl">📏 Метрики</div>';var todayMetrics=(state.metrics||{})[today()]||{};DOMAINS.forEach(function(d){html+='<div class="metric-card"><div class="metric-card-title">'+d.emoji+' '+d.name+'</div>';d.metrics.forEach(function(m){var val=todayMetrics[m.id]||'';html+='<div class="metric-input-row"><label>'+m.label+'</label><input type="text" id="m_'+m.id+'" value="'+esc(val)+'" placeholder="'+m.target+'"/></div>'});html+='</div>'});html+='<button class="btn btn-primary btn-block" onclick="saveMetrics()">💾 Сохранить</button></div>';document.getElementById('app').innerHTML=html}
function saveMetrics(){var t=today();if(!state.metrics)state.metrics={};if(!state.metrics[t])state.metrics[t]={};DOMAINS.forEach(function(d){d.metrics.forEach(function(m){var el=document.getElementById('m_'+m.id);if(el&&el.value)state.metrics[t][m.id]=el.value})});save();playSuccessSound();toast('💾 Сохранено','success');haptic('success')}

/* ПЕРСОНАЛЬНЫЙ ПЛАН */
function renderPersonalPlan(){var plan=state.profile.personalPlan;if(!plan){return placeholderPage('🎯','Персональный план','Пройди опросник в профиле')}var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">Твой план</div>';html+='<div class="insight-card"><div class="insight-title">✨ Фокус</div><div class="insight-text">'+plan.focusDomains.map(function(d){var dom=DOMAINS.find(function(x){return x.id===d});return dom?dom.emoji+' '+dom.name:d}).join(', ')+'</div></div>';plan.days.forEach(function(block){html+='<div class="card"><h2>'+block.title+'</h2>';block.items.forEach(function(item){html+='<div class="plan-day"><div class="plan-time">'+item.time+'</div><div class="plan-title">'+item.title+'</div><div class="plan-desc">'+item.desc+'</div></div>'});html+='</div>'});html+='<button class="btn btn-ghost btn-block" onclick="navigate(\'metrics\')">📏 Заполнить метрики</button></div>';document.getElementById('app').innerHTML=html}

/* ПРОФИЛЬ */
function renderProfile(){var p=state.profile;var unlocked=p.achievements||[];var doneTasks=state.tasks.filter(function(t){return t.status==='completed'}).length;var lessonsDone=Object.keys(state.levelProgress||{}).length;var html='<div class="page">'+backBtn('dashboard');html+='<div class="profile-hero"><div class="profile-avatar" onclick="pickEmoji()">'+p.emoji+'</div><div class="profile-name">'+esc(p.name||'Пользователь')+'</div></div>';html+='<div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+doneTasks+'</div><div class="stat-label">Задач</div></div><div class="stat-item"><div class="stat-value">'+lessonsDone+'</div><div class="stat-label">Уроков</div></div><div class="stat-item"><div class="stat-value">'+(state.stats.streak||0)+'</div><div class="stat-label">Streak</div></div></div>';html+='<div class="card"><h2>✏️ Имя</h2><div class="field" style="margin-bottom:0;"><input type="text" id="profile-name" value="'+esc(p.name)+'" onchange="saveProfileName(this.value)"/></div></div>';if(!p.surveyDone){html+='<div class="card" style="background:linear-gradient(135deg,rgba(255,169,64,.15),rgba(255,107,107,.1));border-color:rgba(255,169,64,.3);"><h2>📋 Опросник</h2><button class="btn btn-primary btn-block" onclick="startSurvey()">Начать</button></div>'}else{html+='<div class="card"><h2>📋 Профиль заполнен</h2><button class="btn btn-ghost btn-block" onclick="if(confirm(\'Заново?\')){state.profile.surveyDone=false;state.profile.surveyStep=0;save();startSurvey();}">Пройти заново</button></div>'}html+='<div class="card"><h2>🏆 Достижения ('+unlocked.length+'/'+ACHIEVEMENTS.length+')</h2><div class="achieve-grid">';ACHIEVEMENTS.forEach(function(a){var isUnlocked=unlocked.indexOf(a.id)>=0;html+='<div class="achieve-item '+(isUnlocked?'unlocked':'locked')+'"><div class="achieve-icon">'+a.icon+'</div><div class="achieve-name">'+a.name+'</div></div>'});html+='</div></div></div>';document.getElementById('app').innerHTML=html}
function pickEmoji(){var emojis=['😊','😎','🤓','🧑‍💻','👨‍💼','👩‍💼','🦊','🐱','🐶','🦁','🐼','🦉','🌟','⚡','🔥','💎','🚀','🎯','🧠','💪','🌈','☕','🎨','🎮','🎧','📚','🏃','🧘','🍀','🌸'];var html='<div class="emoji-grid">';emojis.forEach(function(e){var sel=e===state.profile.emoji?' selected':'';html+='<button class="emoji-pick'+sel+'" onclick="setEmoji(\''+e+'\')">'+e+'</button>'});html+='</div>';openSheet('Аватар',html)}
function setEmoji(e){state.profile.emoji=e;save();playClickSound();closeSheet();toast('Обновлено','success');renderProfile();updateHeaderAvatar()}
function saveProfileName(name){state.profile.name=(name||'').trim()||'Пользователь';save();playSuccessSound();toast('Сохранено','success');updateHeaderAvatar()}
function updateHeaderAvatar(){var el=document.getElementById('headerAvatar');if(el)el.textContent=state.profile.emoji||'👤'}

/* НАСТРОЙКИ */
function renderSettings(){var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">⚙️ Настройки</div>';html+='<div class="card"><h2>Профиль</h2><div class="field"><label class="field-label">Имя</label><input type="text" id="s-name" value="'+esc(state.profile.name)+'" onchange="saveProfileName(this.value)"/></div><div class="list-row" onclick="openThemePicker()"><div class="list-icon" style="background:var(--surface-3);">🎨</div><div class="list-body"><div class="list-title">Тема</div></div><div class="list-value">'+(THEMES.find(function(t){return t.id===state.settings.theme})||{}).name+'</div></div></div>';html+='<div class="card"><h2>AI</h2><div class="list-row" onclick="openAISettings()"><div class="list-icon" style="background:var(--brand);">✨</div><div class="list-body"><div class="list-title">'+state.settings.provider+'</div><div class="list-subtitle">'+(state.settings.apiKey?'Ключ установлен':'Не задан')+'</div></div><div class="list-chevron">›</div></div></div>';html+='<div class="card"><h2>Интеграции</h2><div class="list-row" onclick="navigate(\'integrations\')"><div class="list-icon" style="background:var(--surface-3);">🔗</div><div class="list-body"><div class="list-title">Google, Obsidian, Notion, Todoist, Gemini</div></div><div class="list-chevron">›</div></div></div>';html+='<div class="card"><h2>Данные</h2><div class="list-row" onclick="navigate(\'storage\')"><div class="list-icon" style="background:var(--coach);color:#000;">🗄</div><div class="list-body"><div class="list-title">Хранилище</div></div><div class="list-chevron">›</div></div><div class="list-row" onclick="navigate(\'dbmanager\')"><div class="list-icon" style="background:var(--success);color:#000;">💾</div><div class="list-body"><div class="list-title">База данных</div></div><div class="list-chevron">›</div></div></div>';html+='<div class="footnote text-tertiary" style="text-align:center;margin-top:36px;">AI Health v29</div></div>';document.getElementById('app').innerHTML=html}
function renderDBManager(){var total=state.tasks.length+state.chats.length+state.notes.length+Object.keys(state.levelProgress||{}).length+Object.keys(state.englishProgress||{}).length+(state.watched||[]).length;var html='<div class="page">'+backBtn('settings')+'<div class="title-xl">💾 База</div><div class="card"><div class="list-row"><div class="list-icon" style="background:var(--success);color:#000;">✓</div><div class="list-body"><div class="list-title">LocalStorage</div><div class="list-subtitle">'+STORAGE_KEY+'</div></div></div><div class="list-row"><div class="list-icon" style="background:var(--brand);">📦</div><div class="list-body"><div class="list-title">Записей</div></div><div class="list-value">'+total+'</div></div></div>';html+='<div class="card"><h2>Операции</h2><button class="btn btn-primary btn-block mb-2" onclick="exportDB()">📤 Экспорт</button><button class="btn btn-ghost btn-block mb-2" onclick="document.getElementById(\'importDB\').click()">📥 Импорт</button><input type="file" id="importDB" accept=".json" style="display:none" onchange="importDB(event)"/><button class="btn btn-danger btn-block" onclick="if(confirm(\'Сброс?\')){localStorage.removeItem(\''+STORAGE_KEY+'\');location.reload();}">🗑 Сброс</button></div></div>';document.getElementById('app').innerHTML=html}
function renderStorage(){var totalSize=0;try{var raw=localStorage.getItem(STORAGE_KEY);totalSize=raw?raw.length:0}catch(e){}var html='<div class="page">'+backBtn('settings')+'<div class="title-xl">🗄 Хранилище</div>';html+='<div class="card"><h2>💾 Основное</h2><div class="list-row"><div class="list-icon" style="background:var(--success);color:#000;">✓</div><div class="list-body"><div class="list-title">LocalStorage</div><div class="list-subtitle">'+STORAGE_KEY+'</div></div><div class="list-value">'+(totalSize/1024).toFixed(1)+' KB</div></div></div>';html+='<div class="card"><h2>⚙️ Операции</h2><button class="btn btn-primary btn-block mb-2" onclick="exportDB()">📤 Экспорт JSON</button><button class="btn btn-ghost btn-block mb-2" onclick="document.getElementById(\'importDB\').click()">📥 Импорт JSON</button><input type="file" id="importDB" accept=".json" style="display:none" onchange="importDB(event)"/><button class="btn btn-danger btn-block" onclick="if(confirm(\'Сброс?\')){localStorage.removeItem(\''+STORAGE_KEY+'\');location.reload();}">🗑 Полный сброс</button></div></div>';document.getElementById('app').innerHTML=html}
function exportDB(){var blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});var url=URL.createObjectURL(blob);var a=document.createElement('a');a.href=url;a.download='ai-health-'+today()+'.json';a.click();URL.revokeObjectURL(url);toast('Экспорт готов','success');playSuccessSound()}
function importDB(e){var file=e.target.files[0];if(!file)return;var reader=new FileReader();reader.onload=function(ev){try{var data=JSON.parse(ev.target.result);if(!confirm('Заменить текущие данные?'))return;state=Object.assign(defaultState(),data);save();toast('Импорт успешен','success');playSuccessSound();location.reload()}catch(err){toast('Ошибка','error');playErrorSound()}};reader.readAsText(file)}

