function renderMatrix(){var matrix={q1:[],q2:[],q3:[],q4:[]};state.tasks.forEach(function(t){if(t.status==='completed')return;var important=t.priority==='high'||t.priority==='medium';var urgent=t.due_date?daysBetween(today(),t.due_date.slice(0,10))<=2:false;var q;if(important&&urgent)q='q1';else if(important&&!urgent)q='q2';else if(!important&&urgent)q='q3';else q='q4';matrix[q].push(t)});var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">🔢 Матрица Эйзенхауэра</div><div class="matrix-grid-2x2"><div class="matrix-quadrant matrix-q1"><div class="matrix-q-title">🔥 Q1</div><div class="matrix-q-count" style="color:var(--danger);">'+matrix.q1.length+'</div><div class="matrix-q-sub">Делай сейчас</div></div><div class="matrix-quadrant matrix-q2"><div class="matrix-q-title">📌 Q2</div><div class="matrix-q-count" style="color:var(--brand);">'+matrix.q2.length+'</div><div class="matrix-q-sub">Планируй</div></div><div class="matrix-quadrant matrix-q3"><div class="matrix-q-title">⚡ Q3</div><div class="matrix-q-count" style="color:var(--warning);">'+matrix.q3.length+'</div><div class="matrix-q-sub">Делегируй</div></div><div class="matrix-quadrant matrix-q4"><div class="matrix-q-title">🗑 Q4</div><div class="matrix-q-count" style="color:var(--text-3);">'+matrix.q4.length+'</div><div class="matrix-q-sub">Удали</div></div></div></div>';document.getElementById('app').innerHTML=html}

