function renderIntegrations(){var g=state.integrations.googleCalendar||{};var o=state.integrations.obsidian||{};var gem=state.integrations.gemini||{};var n=state.integrations.notion||{};var t=state.integrations.todoist||{};var hasKey=gem&&gem.apiKey;var html='<div class="page">'+backBtn('settings')+'<div class="title-xl">🔗 Интеграции</div>';html+='<div class="integration-card"><div class="integration-header"><div class="integration-icon">📅</div><div style="flex:1;"><div class="integration-title">Google Calendar</div><div class="integration-status">'+(g.connected?'✓ Подключено':'Не подключено')+'</div></div></div><div class="field mt-3"><label class="field-label">Client ID</label><input type="text" id="gcal-id" value="'+esc(g.clientId||'')+'"/></div><button class="btn btn-primary btn-block" onclick="saveGCal()">💾 Сохранить</button><button class="btn btn-success btn-block mt-2" onclick="if(window.GCAL_API)GCAL_API.authorize()">🔓 Авторизоваться</button><button class="btn btn-ghost btn-block mt-2" onclick="if(window.__syncTasksToGCal)__syncTasksToGCal()">📤 Синхронизировать</button></div>';html+='<div class="integration-card"><div class="integration-header"><div class="integration-icon">🔮</div><div style="flex:1;"><div class="integration-title">Obsidian</div><div class="integration-status">'+(o.apiKey?'✓ Подключено':'Не подключено')+'</div></div></div><div class="field mt-3"><label class="field-label">API Key</label><input type="password" id="obs-key" value="'+esc(o.apiKey||'')+'"/></div><div class="field"><label class="field-label">Папка</label><input type="text" id="obs-folder" value="'+esc(o.defaultFolder||'AI-Health')+'"/></div><button class="btn btn-primary btn-block" onclick="saveObsidian()">💾 Сохранить</button><button class="btn btn-success btn-block mt-2" onclick="if(window.__syncAllToObsidian)__syncAllToObsidian()">📤 Синхронизировать</button></div>';html+='<div class="integration-card"><div class="integration-header"><div class="integration-icon">✨</div><div style="flex:1;"><div class="integration-title">Gemini AI</div><div class="integration-status">'+(hasKey?'✓ Подключено':'Не подключено')+'</div></div></div><div class="field mt-3"><label class="field-label">API Key</label><input type="password" id="gem-key" value="'+esc(gem.apiKey||'')+'"/></div><button class="btn btn-primary btn-block" onclick="saveGemini()">💾 Сохранить</button></div>';html+='</div>';document.getElementById('app').innerHTML=html}
function saveGCal(){state.integrations.googleCalendar.clientId=(document.getElementById('gcal-id')||{}).value||'';state.integrations.googleCalendar.connected=!!state.integrations.googleCalendar.clientId;if(window.GCAL_CONFIG)GCAL_CONFIG.clientId=state.integrations.googleCalendar.clientId;save();if(window.__saveGCalConfig)__saveGCalConfig();playSuccessSound();toast('Сохранено','success');renderIntegrations()}
