function renderWatchlist(){var list=state.watchlist||[];var html='<div class="page">'+backBtn('entertainment')+'<div class="title-xl">📋 Хочу посмотреть</div>';if(list.length){list.forEach(function(w){html+='<div class="list-row"><div class="list-icon" style="background:var(--surface-3);">🎬</div><div class="list-body"><div class="list-title">'+esc(w.title)+'</div><div class="list-subtitle">'+w.type+'</div></div><button class="btn btn-success btn-xs" onclick="promptWatched(\''+w.id+'\')">✓</button></div>'})}else{html+='<div class="empty"><div class="empty-icon">📋</div><div class="empty-title">Пусто</div></div>'}html+='</div>';document.getElementById('app').innerHTML=html}
function promptWatched(id){var rating=prompt('Оценка 1-10:','8');if(rating===null)return;if(window.__markAsWatched){window.__markAsWatched(id,parseInt(rating)||0,'');}else{var item=(state.watchlist||[]).find(function(w){return w.id===id});if(!item)return;if(!state.watched)state.watched=[];state.watched.push({id:id,title:item.title,type:item.type,rating:parseInt(rating)||0,notes:'',watched_at:nowISO()});state.watchlist=state.watchlist.filter(function(w){return w.id!==id});save()}playSuccessSound();renderWatchlist()}
function renderWatched(){var list=state.watched||[];var html='<div class="page">'+backBtn('entertainment')+'<div class="title-xl">✅ Просмотрено</div>';if(list.length){list.forEach(function(w){html+='<div class="list-row"><div class="list-icon" style="background:var(--success);color:#000;">✓</div><div class="list-body"><div class="list-title">'+esc(w.title)+'</div><div class="list-subtitle">'+w.type+' · ⭐'+w.rating+'</div></div></div>'})}else{html+='<div class="empty"><div class="empty-icon">✅</div><div class="empty-title">Пусто</div></div>'}html+='</div>';document.getElementById('app').innerHTML=html}

/* ЭКРАННЫЙ ДЕТОКС */
function renderScreenTracker(){var tips=window.__SCREEN_TIPS||[];var habits=window.__SCREEN_HABITS||[];var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">📱 Экранный детокс</div>';html+='<div class="stat-grid mb-4"><div class="stat-item"><div class="stat-value">'+tips.length+'</div><div class="stat-label">Советов</div></div><div class="stat-item"><div class="stat-value">'+habits.length+'</div><div class="stat-label">Привычек</div></div><div class="stat-item"><div class="stat-value">30</div><div class="stat-label">Дней план</div></div></div>';html+='<div class="card"><h2>🗓 30-дневный план</h2><button class="btn btn-primary btn-block" onclick="navigate(\'detoxplan\')">Открыть</button></div>';var categories={};tips.forEach(function(t){if(!categories[t.category])categories[t.category]=[];categories[t.category].push(t)});Object.keys(categories).forEach(function(cat){html+='<div class="card"><h2>'+cat+'</h2>';categories[cat].forEach(function(t){html+='<div class="screen-card"><div class="screen-title">'+esc(t.title)+'</div><div class="screen-desc">'+esc(t.desc)+'</div><div class="screen-action">→ '+esc(t.action)+'</div><div class="screen-effect">✨ '+esc(t.effect)+' · ⏱ '+esc(t.time)+'</div></div>'});html+='</div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function renderDetoxPlan(){var plan=window.__SCREEN_30_DAY_PLAN||[];var html='<div class="page">'+backBtn('screentracker')+'<div class="title-xl">🗓 30-дневный план</div>';plan.forEach(function(d){html+='<div class="card"><div class="row-between"><div class="badge badge-brand">День '+d.day+'</div><div class="footnote text-tertiary">'+esc(d.tip)+'</div></div><div class="plan-title mt-2">'+esc(d.title)+'</div><div class="plan-desc">'+esc(d.task)+'</div></div>'});html+='</div>';document.getElementById('app').innerHTML=html}
function renderScreenTime(){renderScreenTracker()}

/* ПЛАН ДНЯ */
function renderDailyPlan(){var todayTasks=state.tasks.filter(function(t){return t.status==='pending'});var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">📋 План дня</div>';html+='<div class="card"><h2>🌅 Утро</h2><div class="plan-day"><div class="plan-time">7:30</div><div class="plan-title">Пробуждение</div><div class="plan-desc">Вода + свет</div></div><div class="plan-day"><div class="plan-time">7:45</div><div class="plan-title">Дыхание 4-7-8</div></div><div class="plan-day"><div class="plan-time">8:00</div><div class="plan-title">Движение 15 мин</div></div></div>';html+='<div class="card"><h2>☀️ День</h2><div class="plan-day"><div class="plan-time">9:00</div><div class="plan-title">Deep Work 90 мин</div></div><div class="plan-day"><div class="plan-time">12:00</div><div class="plan-title">Обед</div></div><div class="plan-day"><div class="plan-time">14:00</div><div class="plan-title">Медитация 10 мин</div></div></div>';html+='<div class="card"><h2>🌙 Вечер</h2><div class="plan-day"><div class="plan-time">20:00</div><div class="plan-title">Рефлексия</div></div><div class="plan-day"><div class="plan-time">21:00</div><div class="plan-title">Без экранов</div></div><div class="plan-day"><div class="plan-time">22:30</div><div class="plan-title">Сон</div></div></div>';html+='<div class="card"><h2>📌 Задачи ('+todayTasks.length+')</h2>';todayTasks.slice(0,10).forEach(function(t){html+=taskRow(t)});html+='</div></div>';document.getElementById('app').innerHTML=html}

/* AI */
function renderAI(){var active=state.settings.activePersona||'coach';var persona=PERSONAS[active]||PERSONAS.coach;var messages=state.chats.filter(function(c){return c.persona===active});var hasKey=!!(state.settings.apiKey||(state.integrations.gemini&&state.integrations.gemini.apiKey));var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">✨ AI</div><div class="persona-bar">';Object.keys(PERSONAS).forEach(function(k){var p=PERSONAS[k];html+='<button class="persona-item '+(active===k?'active':'')+'" data-p="'+k+'" onclick="switchPersona(\''+k+'\')">'+p.name+'</button>'});html+='</div>';html+='<div class="card" style="padding:16px 18px;"><div class="row-between"><div class="row" style="gap:12px;"><div style="font-size:28px;">'+persona.emoji+'</div><div><div style="font-weight:700;font-size:16px;">'+persona.name+'</div><div class="caption text-tertiary">'+persona.label+(hasKey?'':' · Demo')+'</div></div></div><button class="btn btn-ghost btn-sm" onclick="openAISettings()">⚙️</button></div></div>';html+='<div class="card" style="min-height:360px;max-height:62vh;overflow-y:auto;padding:18px;" id="chatBox"><div class="chat">';if(messages.length){messages.forEach(function(m){html+='<div class="msg msg-'+(m.role==='user'?'user':'bot')+'">'+(m.role==='user'?esc(m.text):renderMd(m.text))+'</div>'})}else{html+='<div class="empty"><div class="empty-icon">'+persona.emoji+'</div><div class="empty-title">'+persona.name+'</div><div class="empty-text">Задай вопрос</div></div>'}html+='</div></div>';html+='<div class="row" style="margin-top:14px;"><input type="text" id="chatInput" placeholder="Сообщение..." style="flex:1;" onkeydown="if(event.key===\'Enter\'){event.preventDefault();sendMsg();}"/><button class="btn btn-primary btn-icon" onclick="sendMsg()">➤</button></div></div>';document.getElementById('app').innerHTML=html;var box=document.getElementById('chatBox');if(box)box.scrollTop=box.scrollHeight}
function switchPersona(p){state.settings.activePersona=p;save();playClickSound();renderAI()}
async function sendMsg(){var input=document.getElementById('chatInput');if(!input)return;var text=input.value.trim();if(!text)return;input.value='';input.disabled=true;var persona=state.settings.activePersona||'coach';state.chats.push({id:uid(),persona:persona,role:'user',text:text,timestamp:nowISO()});save();playClickSound();renderAI();var box=document.getElementById('chatBox');var typing=document.createElement('div');typing.className='typing';typing.innerHTML='<span></span><span></span><span></span>';if(box){box.appendChild(typing);box.scrollTop=box.scrollHeight}var reply=await callAI(persona,text);if(typing)typing.remove();state.chats.push({id:uid(),persona:persona,role:'coach',text:reply,timestamp:nowISO()});save();checkAchievements();renderAI()}
async function callAI(persona,userText){var key=state.settings.apiKey||(state.integrations.gemini&&state.integrations.gemini.apiKey);var provider=state.settings.provider||'gemini';if(!key)return fallbackReply(persona,userText);var p=PERSONAS[persona];var history=state.chats.filter(function(c){return c.persona===persona}).slice(-10);var messages=[{role:'system',content:p.prompt}];history.forEach(function(m){messages.push({role:m.role==='user'?'user':'assistant',content:m.text})});try{if(provider==='openai'){var resp=await fetch('https://api.openai.com/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+key},body:JSON.stringify({model:'gpt-4o-mini',messages:messages,temperature:.8,max_tokens:800})});var data=await resp.json();return (data.choices&&data.choices[0]&&data.choices[0].message&&data.choices[0].message.content)||fallbackReply(persona,userText)}else{var sys=p.prompt;var rest=history.map(function(m){return{role:m.role==='user'?'user':'model',parts:[{text:m.text}]}});var model=(state.integrations.gemini&&state.integrations.gemini.model)||'gemini-1.5-flash';var resp3=await fetch('https://generativelanguage.googleapis.com/v1beta/models/'+model+':generateContent?key='+key,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({system_instruction:{parts:[{text:sys}]},contents:rest})});var data3=await resp3.json();return (data3.candidates&&data3.candidates[0]&&data3.candidates[0].content&&data3.candidates[0].content.parts&&data3.candidates[0].content.parts[0]&&data3.candidates[0].content.parts[0].text)||fallbackReply(persona,userText)}}catch(e){console.error(e);return fallbackReply(persona,userText)}}
function fallbackReply(persona,text){text=text||'';if(/суицид|покончить|не хочу жить|умереть/i.test(text)){return '🆘 Позвони: 8-800-2000-122 (РФ) · 103 · findahelpline.com. Ты важен.'}if(persona==='doctor')return 'Я — AI-консультант. Опиши симптомы.\n\n*⚠️ Не заменяет врача.*';if(persona==='psych')return 'Слышу тебя. Что происходит?';return 'Слышу тебя. Расскажи подробнее.'}
function renderMd(text){if(!text)return '';var h=esc(text);h=h.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');h=h.replace(/^[•\-] (.+)$/gm,'<li>$1</li>');h=h.replace(/(<li>[\s\S]*?<\/li>)(?!\s*<li>)/g,'<ul>$1</ul>');h=h.replace(/\n\n/g,'</p><p>');h=h.replace(/\n/g,'<br>');return '<p>'+h+'</p>'}
function openAISettings(){openSheet('Настройки AI','<div class="field"><label class="field-label">Провайдер</label><select id="ai-p"><option value="gemini"'+(state.settings.provider==='gemini'?' selected':'')+'>Google Gemini (бесплатно)</option><option value="openai"'+(state.settings.provider==='openai'?' selected':'')+'>OpenAI</option></select></div><div class="field"><label class="field-label">API ключ</label><input type="password" id="ai-k" value="'+esc(state.settings.apiKey||'')+'"/></div><button class="btn btn-primary btn-block" onclick="saveAISettings()">Сохранить</button>')}
function saveAISettings(){state.settings.provider=(document.getElementById('ai-p')||{}).value||'gemini';state.settings.apiKey=((document.getElementById('ai-k')||{}).value||'').trim();save();playSuccessSound();closeSheet();toast('Сохранено','success');renderAI()}

/* ЗДОРОВЬЕ */
function renderHealth(){var waterEntry=state.water.find(function(w){return w.date===today()});var water=waterEntry?waterEntry.count:0;var waterGoal=state.settings.waterGoal||8;var todayScores=(state.domainScores||{})[today()]||{};var html='<div class="page">'+backBtn('dashboard')+'<div class="title-xl">❤️ Здоровье</div>';html+='<div class="card"><h2>Сегодня</h2><div class="stat-grid"><div class="stat-item" onclick="quickMoodLog()" style="cursor:pointer;"><div class="stat-value">'+(state.mood.length?state.mood[state.mood.length-1].score+'/10':'—')+'</div><div class="stat-label">Настроение</div></div><div class="stat-item" onclick="addWater()" style="cursor:pointer;"><div class="stat-value">'+water+'/'+waterGoal+'</div><div class="stat-label">Вода</div></div><div class="stat-item" onclick="navigate(\'workouts\')" style="cursor:pointer;"><div class="stat-value">'+state.workouts.length+'</div><div class="stat-label">Тренировок</div></div></div></div>';html+='<div class="card"><h2>🌐 Домены</h2>';DOMAINS.forEach(function(d){var score=todayScores[d.id]||0;html+='<div class="list-row" onclick="openDomain(\''+d.id+'\')"><div class="list-icon" style="background:'+d.color+'20;color:'+d.color+';">'+d.emoji+'</div><div class="list-body"><div class="list-title">'+d.name+'</div><div class="list-subtitle">'+(score>0?score+'/10':'Не оценено')+'</div></div><div class="list-chevron">›</div></div>'});html+='</div>';html+='<div class="card"><h2>Быстрый доступ</h2><div class="group-grid"><div class="group-item" onclick="navigate(\'water\')"><div class="group-item-icon">💧</div><div class="group-item-label">Вода</div></div><div class="group-item" onclick="navigate(\'mood\')"><div class="group-item-icon">💭</div><div class="group-item-label">Настроение</div></div><div class="group-item" onclick="navigate(\'workouts\')"><div class="group-item-icon">🏋️</div><div class="group-item-label">Тренировки</div></div><div class="group-item" onclick="navigate(\'meditation\')"><div class="group-item-icon">🧘</div><div class="group-item-label">Медитации</div></div><div class="group-item" onclick="navigate(\'meds\')"><div class="group-item-icon">💊</div><div class="group-item-label">Лекарства</div></div><div class="group-item" onclick="navigate(\'recovery\')"><div class="group-item-icon">🌿</div><div class="group-item-label">Восстановление</div></div></div></div>';html+='<div class="card"><h2>AI-специалисты</h2>';['doctor','nutrition','fitness','psych'].forEach(function(k){var p=PERSONAS[k];html+='<div class="list-row" onclick="openPersona(\''+k+'\')"><div class="list-icon" style="background:var(--'+p.color+');color:#000;">'+p.emoji+'</div><div class="list-body"><div class="list-title">'+p.name+'</div><div class="list-subtitle">'+p.label+'</div></div><div class="list-chevron">›</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function openPersona(p){state.settings.activePersona=p;save();playClickSound();navigate('ai')}
function addWater(){var t=today();var entry=state.water.find(function(w){return w.date===t});if(entry)entry.count++;else state.water.push({id:uid(),date:t,count:1,created_at:nowISO()});state.stats.totalWater=(state.stats.totalWater||0)+1;save();playWaterSound();toast('💧 +1','success');haptic('success');if(currentPage==='dashboard')renderDashboard();else renderHealth()}
function quickMoodLog(){var moods=['😢','😔','😐','🙂','😊'];var html='<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;">';moods.forEach(function(m,i){html+='<button class="btn btn-ghost" style="font-size:36px;padding:24px 0;" onclick="saveMood('+((i+1)*2)+')">'+m+'</button>'});html+='</div>';openSheet('Настроение?',html)}
function saveMood(score){var t=today();var existing=state.mood.find(function(m){return m.date===t});if(existing)existing.score=score;else state.mood.push({id:uid(),date:t,score:score,created_at:nowISO()});state.stats.totalMoodLogs=(state.stats.totalMoodLogs||0)+1;save();playSuccessSound();closeSheet();toast('Записано','success');haptic('success');if(currentPage==='dashboard')renderDashboard();else renderHealth()}

