function renderWater(){var entry=state.water.find(function(w){return w.date===today()});var count=entry?entry.count:0;var goal=state.settings.waterGoal||8;var html='<div class="page">'+backBtn('health')+'<div class="title-xl">💧 Вода</div>';html+='<div class="card card-gradient" style="text-align:center;"><div style="font-size:64px;">💧</div><div style="font-size:44px;font-weight:800;">'+count+'/'+goal+'</div><div class="progress" style="margin-top:14px;background:rgba(255,255,255,.25);height:8px;"><div class="progress-fill" style="width:'+Math.min(100,count/goal*100)+'%;background:#fff;"></div></div></div>';html+='<button class="btn btn-primary btn-block" onclick="addWater();renderWater()">+1 стакан</button>';html+='</div>';document.getElementById('app').innerHTML=html}
function renderMood(){var m=state.mood||[];var html='<div class="page">'+backBtn('health')+'<div class="title-xl">💭 Настроение</div>';html+='<button class="btn btn-primary btn-block mb-4" onclick="quickMoodLog()">Записать настроение</button>';if(m.length){m.slice(-10).reverse().forEach(function(e){html+='<div class="list-row"><div class="list-icon" style="background:var(--surface-3);">'+(e.score>=7?'😊':e.score>=5?'🙂':'😔')+'</div><div class="list-body"><div class="list-title">'+e.date+'</div><div class="list-subtitle">'+e.score+'/10</div></div></div>'})}else{html+='<div class="empty"><div class="empty-icon">💭</div><div class="empty-title">Пусто</div></div>'}html+='</div>';document.getElementById('app').innerHTML=html}
function renderWorkouts(){var w=state.workouts||[];var html='<div class="page">'+backBtn('health')+'<div class="title-xl">🏋️ Тренировки</div>';html+='<div class="card"><div class="stat-row"><span class="stat-row-label">Всего</span><span class="stat-row-value">'+w.length+'</span></div></div>';if(w.length){w.slice(-10).reverse().forEach(function(x){html+='<div class="list-row"><div class="list-icon" style="background:var(--fitness);color:#000;">🏋️</div><div class="list-body"><div class="list-title">'+esc(x.title||'Тренировка')+'</div><div class="list-subtitle">'+x.date+' · '+x.duration+' мин</div></div></div>'})}html+='</div>';document.getElementById('app').innerHTML=html}
function renderMeditation(){var m=state.meditations||[];var html='<div class="page">'+backBtn('health')+'<div class="title-xl">🧘 Медитации</div>';html+='<div class="card"><div class="stat-row"><span class="stat-row-label">Всего</span><span class="stat-row-value">'+m.length+'</span></div></div>';html+='</div>';document.getElementById('app').innerHTML=html}
