function renderJournal(){var entries=state.journalEntries||[];var html='<div class="page">'+backBtn('more')+'<div class="title-xl">📓 Дневник</div>';html+='<div class="card"><button class="btn btn-primary btn-block" onclick="addJournalEntry()">+ Новая запись</button></div>';if(entries.length){entries.slice(-10).reverse().forEach(function(e){html+='<div class="card"><div class="footnote text-tertiary">'+e.date+'</div><div style="margin-top:8px;">'+esc(e.content).slice(0,200)+'</div></div>'})}html+='</div>';document.getElementById('app').innerHTML=html}
function addJournalEntry(){var content=prompt('Запись:');if(!content)return;if(!state.journalEntries)state.journalEntries=[];state.journalEntries.push({id:uid(),date:today(),content:content,created_at:nowISO()});save();playSuccessSound();renderJournal()}
function renderNotes(){var notes=state.customNotes||state.notes||[];var html='<div class="page">'+backBtn('more')+'<div class="title-xl">📝 Заметки</div>';html+='<div class="card"><button class="btn btn-primary btn-block" onclick="addNote()">+ Новая заметка</button></div>';if(notes.length){notes.slice(-10).reverse().forEach(function(n){html+='<div class="card"><div class="list-title">'+esc(n.title||'Без названия')+'</div><div class="footnote text-secondary mt-2">'+esc((n.content||'').slice(0,200))+'</div></div>'})}html+='</div>';document.getElementById('app').innerHTML=html}
function addNote(){var title=prompt('Название:');if(!title)return;var content=prompt('Содержание:');if(!state.customNotes)state.customNotes=[];state.customNotes.push({id:uid(),title:title,content:content||'',created_at:nowISO()});save();playSuccessSound();renderNotes()}
function renderGoals(){var goals=state.customGoals||[];var html='<div class="page">'+backBtn('more')+'<div class="title-xl">🎯 Цели</div>';html+='<div class="card"><button class="btn btn-primary btn-block" onclick="addGoal()">+ Новая цель</button></div>';if(goals.length){goals.forEach(function(g){html+='<div class="card"><div class="list-title">'+esc(g.title)+'</div><div class="footnote text-secondary">'+esc(g.category||'')+'</div></div>'})}html+='</div>';document.getElementById('app').innerHTML=html}
function addGoal(){var title=prompt('Цель:');if(!title)return;if(!state.customGoals)state.customGoals=[];state.customGoals.push({id:uid(),title:title,category:'Личное',created_at:nowISO()});save();playSuccessSound();renderGoals()}
function renderHabits(){var habits=state.customHabits||[];var html='<div class="page">'+backBtn('more')+'<div class="title-xl">🔄 Привычки</div>';html+='<div class="card"><h2>Выбери привычку</h2>';HABITS_TEMPLATES.forEach(function(h){var added=habits.some(function(x){return x.templateId===h.id});html+='<div class="habit-row '+(added?'done':'')+'" onclick="toggleCustomHabit(\''+h.id+'\')"><div class="habit-icon">'+h.icon+'</div><div class="habit-body"><div class="habit-title">'+h.title+'</div><div class="habit-streak">'+h.category+'</div></div><div class="habit-check">'+(added?'✓':'')+'</div></div>'});html+='</div></div>';document.getElementById('app').innerHTML=html}
function toggleCustomHabit(templateId){if(!state.customHabits)state.customHabits=[];var idx=state.customHabits.findIndex(function(x){return x.templateId===templateId});var tpl=HABITS_TEMPLATES.find(function(h){return h.id===templateId});if(idx>=0){state.customHabits.splice(idx,1)}else{state.customHabits.push({id:uid(),templateId:templateId,title:tpl.title,icon:tpl.icon,category:tpl.category,created_at:nowISO()})}save();playClickSound();renderHabits()}
