function showWelcome(){var overlay=document.createElement('div');overlay.className='welcome-screen';overlay.innerHTML='<div class="welcome-logo">🧠</div><div class="welcome-title">AI Health Ecosystem</div><div class="welcome-sub">5 уровней · 5 модулей · 125 уроков English · 45+ тем с живыми эффектами · Досуг · AI.</div><button class="btn btn-primary btn-block" style="max-width:340px;" onclick="startOnboarding()">Начать</button>';document.body.appendChild(overlay)}
function startOnboarding(){var w=document.querySelector('.welcome-screen');if(w)w.remove();var name=window.__tgName||'';if(!name){var overlay=document.createElement('div');overlay.className='welcome-screen';overlay.innerHTML='<div class="welcome-logo">👤</div><div class="welcome-title">Как тебя зовут?</div><input type="text" class="welcome-input" id="welcome-name" placeholder="Имя" maxlength="30"/><button class="btn btn-primary btn-block mt-4" style="max-width:340px;margin-top:16px;" onclick="finishOnboarding()">Далее</button>';document.body.appendChild(overlay);setTimeout(function(){var i=document.getElementById('welcome-name');if(i)i.focus()},300)}else{state.profile.name=name;state.settings.onboardingDone=true;save();updateHeaderAvatar();renderTabBar();renderDashboard()}}
function finishOnboarding(){var inp=document.getElementById('welcome-name');var name=inp?inp.value.trim():'';if(!name)return toast('Введи имя','error');state.profile.name=name;state.settings.onboardingDone=true;save();var w=document.querySelector('.welcome-screen');if(w)w.remove();updateHeaderAvatar();renderTabBar();renderDashboard();playLevelUpSound();haptic('success');toast('Добро пожаловать, '+name+'!','success')}
function init(){try{applyTheme(state.settings.theme);updateHeaderAvatar();if(!state.profile.name&&!state.settings.onboardingDone){showWelcome();return}if(state.profile.name&&!state.settings.onboardingDone){state.settings.onboardingDone=true;save()}if(!state.profile.name&&window.__tgName){state.profile.name=window.__tgName;save();updateHeaderAvatar()}if(state.tasks.length===0){state.tasks=[{id:uid(),title:'Завершить отчёт',category:'Работа',planned_time:45,actual_time:0,status:'pending',priority:'high',created_at:nowISO()},{id:uid(),title:'Повторить 10 слов',category:'Обучение',planned_time:15,actual_time:0,status:'pending',priority:'medium',created_at:nowISO()},{id:uid(),title:'Дневник: 3 победы',category:'Личное',planned_time:5,actual_time:0,status:'pending',priority:'medium',created_at:nowISO()}];save()}if(!state.englishProgress)state.englishProgress={};if(!state.entertainment)state.entertainment=[];if(!state.watchlist)state.watchlist=[];if(!state.watched)state.watched=[];if(!state.memoryTraining)state.memoryTraining=[];if(!state.customHabits)state.customHabits=[];if(!state.customGoals)state.customGoals=[];if(!state.customNotes)state.customNotes=[];if(!state.journalEntries)state.journalEntries=[];renderTabBar();renderDashboard();var t=today();if(state.stats.lastActiveDay!==t){var y=new Date();y.setDate(y.getDate()-1);var wasYesterday=state.stats.lastActiveDay===y.toISOString().slice(0,10);state.stats.streak=wasYesterday?(state.stats.streak||0)+1:1;if(state.stats.streak>(state.stats.bestStreak||0))state.stats.bestStreak=state.stats.streak;state.stats.lastActiveDay=t;save()}if('requestIdleCallback' in window){requestIdleCallback(function(){try{checkAchievements()}catch(e){}},{timeout:2000})}else{setTimeout(function(){try{checkAchievements()}catch(e){}},1000)}if(window.__initIntegrationsExt){try{window.__initIntegrationsExt()}catch(e){}}}catch(e){console.error('Init:',e);var app=document.getElementById('app');if(app)app.innerHTML='<div class="empty"><div class="empty-icon">⚠️</div><div class="empty-title">Ошибка</div><div class="empty-text">'+esc(e.message)+'</div></div>'}}
function attachRipple(){document.addEventListener('pointerdown',function(e){var target=e.target.closest('.btn, .list-row, .chip, .tab-item, .task-item, .card, .icon-btn, .avatar-btn, .persona-item, .segmented-item, .level-card, .module-card, .lesson-row, .emoji-pick, .domain-card, .method-card, .course-card, .path-step, .survey-option, .ent-card, .screen-card, .habit-row, .group-item, .back-btn');if(!target)return;target.classList.add('tap-ripple');var rect=target.getBoundingClientRect();target.style.setProperty('--rx',((e.clientX-rect.left)/rect.width)*100+'%');target.style.setProperty('--ry',((e.clientY-rect.top)/rect.height)*100+'%');target.classList.remove('rippling');void target.offsetWidth;target.classList.add('rippling');setTimeout(function(){target.classList.remove('rippling')},700)},{passive:true})}

